from langgraph.prebuilt import ToolNode
from langgraph.types import interrupt, Command
from langgraph.checkpoint.memory import InMemorySaver


def create_circle():
    return interrupt({"tool": "circle", "question": "approve circle?"})

def create_square():
    return interrupt({"tool": "square", "question": "approve square?"})

def create_triangle():
    return interrupt({"tool": "triangle", "question": "approve triangle?"})

